css:
@page { size: A4 landscape; margin: 0; }

/* Read by Frappe's PDF generator, which ignores @page size. */
.print-format {
	orientation: landscape;
	padding: 0 !important;
}

.uc-page {
	font-family: "Be Vietnam Pro", "Inter", sans-serif;
	color: #1f2333;
	width: 297mm;
	height: 209mm;
	box-sizing: border-box;
	padding: 14mm;
	background: #ffffff;
}

.uc-card {
	position: relative;
	box-sizing: border-box;
	height: 100%;
	padding: 14mm 18mm;
	border-radius: 18px;
	border: 1px solid #d5d6de;
	background: linear-gradient(135deg, #f4f4f8 0%, #e9e9f2 100%);
	display: flex;
	flex-direction: column;
}

.uc-header {
	display: flex;
	justify-content: space-between;
	align-items: flex-start;
}

.uc-brand {
	display: flex;
	align-items: center;
	gap: 10px;
}

.uc-logo {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 38px;
	height: 38px;
	border-radius: 9px;
	background: #4f4cc4;
}

.uc-logo-img {
	height: 38px;
}

.uc-brand-name {
	font-size: 22px;
	font-weight: 800;
	letter-spacing: -0.3px;
}

.uc-badge {
	margin-top: -4mm;
}

.uc-badge-brand {
	font-family: "Be Vietnam Pro", sans-serif;
	font-size: 11px;
	font-weight: 800;
	fill: #2b2a6e;
}

.uc-badge-label {
	font-family: "Be Vietnam Pro", sans-serif;
	font-size: 8px;
	font-weight: 700;
	letter-spacing: 1.5px;
	fill: #2b2a6e;
}

.uc-body {
	flex: 1;
	display: flex;
	flex-direction: column;
	justify-content: center;
	max-width: 72%;
}

.uc-title {
	font-size: 13px;
	font-weight: 700;
	letter-spacing: 3px;
	color: #4f4cc4;
	margin-bottom: 8mm;
}

.uc-lead {
	font-size: 17px;
	margin-bottom: 3mm;
}

.uc-name {
	font-size: 38px;
	font-weight: 800;
	letter-spacing: -0.5px;
	margin-bottom: 4mm;
}

.uc-text {
	font-size: 17px;
	line-height: 1.6;
}

.uc-footer {
	display: flex;
	justify-content: space-between;
	align-items: flex-end;
	border-top: 1px solid #d5d6de;
	padding-top: 5mm;
}

.uc-label {
	font-size: 12px;
	color: #7a7d8c;
	margin-bottom: 1.5mm;
}

.uc-value {
	font-size: 16px;
	font-weight: 700;
}

.uc-id {
	text-align: right;
}

.uc-id .uc-value {
	font-family: monospace;
	font-size: 13px;
	font-weight: 500;
	color: #4a4d5c;
}
